SELECT gen_random_uuid()::text, 'formula', '$\frac{2A\sin(\omega\tau/2)}{\omega}$', 'Fourier Transforms of a Pulse and a Decaying Exponential', '$\text{pulse } (A, \text{width } \tau): \frac{2A\sin(\omega\tau/2)}{\omega} = A\tau\,\text{sinc}\frac{\omega\tau}{2};\qquad e^{-at}u(t): \frac{1}{a + j\omega}$', NULL, 'Two transforms everything else is built from.', '[{"symbol":"$A, \\tau$","meaning":"pulse height and width"},{"symbol":"$a$","meaning":"decay rate, positive"}]'::jsonb, 'The pulse''s first zero is at $\omega = \frac{2\pi}{\tau}$: narrower pulse, wider spectrum.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'fourier transforms' AND s."active"), NULL, true, 'PENDING', now(), now()
