SELECT gen_random_uuid()::text, 'formula', '$\frac{z}{z - a}$', 'Common Z-Transforms', '$\delta[n] \to 1,\quad u[n] \to \frac{z}{z - 1},\quad a^nu[n] \to \frac{z}{z - a},\quad nu[n] \to \frac{z}{(z - 1)^2}$', NULL, 'The transforms most problems reduce to.', '[{"symbol":"$a$","meaning":"a constant"},{"symbol":"$u[n]$","meaning":"the unit step sequence"}]'::jsonb, '$a^n$ converges for $|z| > |a|$; a pole inside the unit circle is a decaying sequence.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'z-transforms' AND s."active"), NULL, true, 'PENDING', now(), now()
