SELECT gen_random_uuid()::text, 'formula', '$J_n(x)$', 'Bessel''s Equation and Its Series', '$x^2y'''' + xy'' + (x^2 - n^2)y = 0,\qquad J_n(x) = \sum_{k=0}^\infty\frac{(-1)^k}{k!\,(n + k)!}\left(\frac{x}{2}\right)^{2k+n}$', NULL, 'The equation of drums, cylinders and FM sidebands, and its standard solution.', '[{"symbol":"$n$","meaning":"the order"},{"symbol":"$J_n$","meaning":"the Bessel function of the first kind"}]'::jsonb, 'General solution: $C_1J_n(x) + C_2Y_n(x)$; $Y_n$ blows up at $x = 0$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'bessel and legendre functions' AND s."active"), 'Bessel', true, 'PENDING', now(), now()
