SELECT gen_random_uuid()::text, 'formula', '$J_{n-1} + J_{n+1}$', 'Bessel Recurrence Relations', '$J_{n-1} + J_{n+1} = \frac{2n}{x}J_n,\qquad \frac{d}{dx}\left[x^nJ_n\right] = x^nJ_{n-1},\qquad J_0'' = -J_1$', NULL, 'Relations that get any order from two neighbours.', '[{"symbol":"$J_n$","meaning":"Bessel functions of the first kind"}]'::jsonb, '$J_{-n} = (-1)^nJ_n$ for whole $n$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'bessel and legendre functions' AND s."active"), 'Bessel', true, 'PENDING', now(), now()
