SELECT gen_random_uuid()::text, 'formula', '$P_n(x)$', 'Legendre Polynomials', '$(1 - x^2)y'''' - 2xy'' + n(n + 1)y = 0;\quad P_0 = 1,\ P_1 = x,\ P_2 = \tfrac{3x^2 - 1}{2},\ P_3 = \tfrac{5x^3 - 3x}{2}$', NULL, 'Legendre''s equation and its polynomial solutions.', '[{"symbol":"$n$","meaning":"the degree"}]'::jsonb, '$P_n(1) = 1$ and $P_n(-1) = (-1)^n$ for every $n$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'bessel and legendre functions' AND s."active"), 'Legendre', true, 'PENDING', now(), now()
