SELECT gen_random_uuid()::text, 'formula', '$\int P_mP_n$', 'Rodrigues'' Formula and Orthogonality', '$P_n = \frac{1}{2^nn!}\frac{d^n}{dx^n}(x^2 - 1)^n,\qquad \int_{-1}^1P_mP_n\,dx = \begin{cases}0 & m \ne n\\ \frac{2}{2n + 1} & m = n\end{cases}$', NULL, 'A closed form for every Legendre polynomial, and why they expand functions like sines do.', '[{"symbol":"$m, n$","meaning":"degrees"}]'::jsonb, 'Orthogonality on [−1, 1] is what Legendre series rest on.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'bessel and legendre functions' AND s."active"), 'Legendre', true, 'PENDING', now(), now()
