SELECT gen_random_uuid()::text, 'formula', '$u_t = c^2u_{xx}$', 'Heat Equation', '$u_t = c^2u_{xx},\quad u(0, t) = u(L, t) = 0:\quad u = \sum b_n\sin\frac{n\pi x}{L}\,e^{-(n\pi c/L)^2t}$', NULL, 'Temperature along a rod with its ends held at zero, by separation of variables.', '[{"symbol":"$c^2$","meaning":"the diffusivity"},{"symbol":"$L$","meaning":"the length"},{"symbol":"$b_n$","meaning":"the Fourier sine coefficients of the initial temperature"}]'::jsonb, 'Higher harmonics die out fastest: the profile smooths toward the first mode.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'partial differential equations' AND s."active"), NULL, true, 'PENDING', now(), now()
