INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\nabla^2u = 0$', 'Laplace''s Equation and PDE Types', '$u_{xx} + u_{yy} = 0;\qquad Au_{xx} + Bu_{xy} + Cu_{yy}: B^2 - 4AC < 0 \text{ elliptic},\ = 0 \text{ parabolic},\ > 0 \text{ hyperbolic}$', NULL, 'Steady-state fields, and how to classify a second-order PDE.', '[{"symbol":"$A, B, C$","meaning":"coefficients of the second derivatives"}]'::jsonb, 'Laplace is elliptic, heat parabolic, wave hyperbolic: the same test as for conics.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'partial differential equations' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$u_x = v_y$', 'Cauchy-Riemann Equations', '$f = u + jv \text{ analytic} \iff u_x = v_y,\quad u_y = -v_x$', NULL, 'The test for a complex function to be differentiable.', '[{"symbol":"$u, v$","meaning":"the real and imaginary parts of f(z)"}]'::jsonb, 'Then $f''(z) = u_x + jv_x$, and $u$, $v$ each satisfy Laplace''s equation.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'functions of a complex variable' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\oint\frac{f(z)}{z - z_0}dz$', 'Cauchy''s Integral Theorem and Formula', '$\oint_C f(z)\,dz = 0,\qquad f(z_0) = \frac{1}{2\pi j}\oint_C\frac{f(z)}{z - z_0}\,dz$', NULL, 'Integrals of analytic functions round a loop are zero, except where a pole sits.', '[{"symbol":"$C$","meaning":"a closed path around $z_0$, traversed counterclockwise"},{"symbol":"$f$","meaning":"analytic on and inside C"}]'::jsonb, 'Derivatives too: $f^{(n)}(z_0) = \frac{n!}{2\pi j}\oint\frac{f}{(z - z_0)^{n+1}}dz$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'functions of a complex variable' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$2\pi j\sum\text{Res}$', 'Residue Theorem', '$\oint_C f(z)\,dz = 2\pi j\sum\text{Res}(f, z_k),\qquad \text{simple pole: Res} = \lim_{z \to z_k}(z - z_k)f(z) = \frac{P(z_k)}{Q''(z_k)}$', NULL, 'A contour integral from the residues at the poles inside it.', '[{"symbol":"$z_k$","meaning":"the poles inside C"},{"symbol":"$P, Q$","meaning":"$f = \\frac{P}{Q}$"}]'::jsonb, 'Only poles inside the contour count.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics' AND s."normKey" = 'functions of a complex variable' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Advanced Engineering Mathematics' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
